import CryptoKit
import Foundation

// Unit F self tests: model-free. The expected values come from the former Python sweep.py and the former Python polish.py on the same
// inputs (VaultSweepExpected.swift, generated by scripts/ne-f/gen_expected.py).

enum VaultSweepSelfTest {
    static let expected: [String: Any] = {
        let data = Data(VaultSweepExpected.json.utf8)
        return (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] ?? [:]
    }()

    static func sha(_ s: String) -> String { SHA256.hash(data: Data(s.utf8)).map { String(format: "%02x", $0) }.joined() }

    static func run() -> Bool {
        var ok = true
        func check(_ cond: Bool, _ what: String) {
            if !cond { ok = false; print("FAIL vault sweep: \(what)") }
        }
        let e = expected
        guard !e.isEmpty else { print("FAIL vault sweep: expected values unreadable"); return false }

        // Prompts, byte for byte.
        let h = e["hashes"] as! [String: String]
        check(sha(VaultSweep.extractPrompt) == h["extract"], "extract prompt differs from sweep.py")
        check(sha(VaultSweep.domainPrompt) == h["domain"], "domain prompt differs from sweep.py")

        // Rule pipeline per note (extract_rules).
        for n in e["notes"] as! [[String: Any]] {
            let stem = n["stem"] as! String
            let got = SweepRules.extractRules(n["text"] as! String, stem: stem).map { "\($0.term)|\($0.category)|\($0.count)|\($0.alias)" }
            let want = (n["terms"] as! [[String: Any]]).map { "\($0["term"]!)|\($0["category"]!)|\($0["count"]!)|\(($0["alias"] as! Bool))" }
            check(got == want, "extract_rules for note \(stem): \(got) vs \(want)")
        }
        // plausible()
        for p in e["plausible"] as! [[String: Any]] {
            let term = p["term"] as! String
            check(SweepRules.plausible(term, p["category"] as! String, lowercaseToo: p["lower"] as! Bool) == (p["ok"] as! Bool), "plausible(\(term))")
        }
        // chunks (2,000-character pieces of a note), plain()
        let c = e["chunks"] as! [String: Any]
        check(SweepRules.chunks(c["text"] as! String) == c["default"] as! [String], "chunks default")
        check(SweepRules.chunks(c["text"] as! String, size: c["size"] as! Int) == c["small"] as! [String], "chunks small")
        for p in e["plain"] as! [[String: Any]] {
            let (body, aliases) = SweepRules.plain(p["text"] as! String)
            check(body == p["body"] as! String, "plain body")
            check(aliases == p["aliases"] as! [String], "plain aliases")
        }
        for o in e["oneedit"] as! [[String: Any]] {
            check(SweepRank.oneEdit(o["a"] as! String, o["b"] as! String) == (o["ok"] as! Bool), "one_edit(\(o["a"]!), \(o["b"]!))")
        }
        // rank(): 2+ notes, MIN_SCORE, recency, merge_variants.
        let r = e["rank"] as! [String: Any]
        let notes = (r["notes"] as! [[String: Any]]).map { n -> (mtime: Double, terms: [SweepTerm]) in
            (n["mtime"] as! Double, (n["terms"] as! [[String: Any]]).map {
                SweepTerm(term: $0["term"] as! String, category: $0["category"] as! String, count: $0["count"] as! Int,
                          alias: $0["alias"] as! Bool, lower: $0["lower"] as! Bool)
            })
        }
        let got = SweepRank.rank(notes, now: r["now"] as! Double)
        let want = r["ranked"] as! [[String: Any]]
        check(got.map(\.term) == want.map { $0["term"] as! String }, "rank order: \(got.map(\.term))")
        check(got.map(\.category) == want.map { $0["category"] as! String }, "rank categories")
        check(got.map(\.notes) == want.map { $0["notes"] as! Int } && got.map(\.count) == want.map { $0["count"] as! Int }, "rank counts")
        check(zip(got, want).allSatisfy { abs($0.score - ($1["score"] as! Double)) < 1e-6 }, "rank scores")
        return ok
    }
}
